// Builds the web version of Konso (installable PWA) into a folder, ready to publish as is.
//   node tools/build-web.js <out-dir>                 the real site
//   node tools/build-web.js <out-dir> --test <branch> a test build ("Konso Test"), published in /test/<branch>/
// Used by the "Publier la version web" workflow (.github/workflows/web.yml); no dependencies.
//
// The site is the app of the APK, app/src/main/assets/www, unchanged, plus what only the web needs,
// from web/ (so none of it ends up in the APK):
// - icons/ (generated by tools/web-icons.js);
// - manifest.webmanifest, written here (name, colours, icons);
// - sw.js, the offline cache, with the list of files and a version hash filled in.
// The OCR language model is stored as "fra.traineddata.gz.bin" in the app (see MainActivity.java): it is
// published under its real name, "fra.traineddata.gz", the one the OCR engine asks for.
const fs = require('fs'),
  path = require('path'),
  crypto = require('crypto');

const ROOT = path.join(__dirname, '..');
const WWW = path.join(ROOT, 'app', 'src', 'main', 'assets', 'www');
const WEB = path.join(ROOT, 'web');

const args = process.argv.slice(2);
const out = args[0];
const ti = args.indexOf('--test');
const test = ti >= 0 ? args[ti + 1] || 'test' : null;
if (!out || out.startsWith('--')) {
  console.error('Usage: node tools/build-web.js <out-dir> [--test <branch>]');
  process.exit(1);
}

// Copy a folder, file by file; returns the published paths (with "/" separators).
function copyDir(src, dst, rel = '', list = []) {
  fs.mkdirSync(dst, { recursive: true });
  for (const e of fs.readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, e.name);
    if (e.isDirectory()) {
      copyDir(s, path.join(dst, e.name), rel + e.name + '/', list);
    } else {
      const name = e.name.endsWith('.gz.bin') ? e.name.slice(0, -4) : e.name;
      fs.copyFileSync(s, path.join(dst, name));
      list.push(rel + name);
    }
  }
  return list;
}

fs.rmSync(out, { recursive: true, force: true });
const files = copyDir(WWW, out);
files.push(...copyDir(path.join(WEB, 'icons'), path.join(out, 'icons'), 'icons/'));

const name = test ? 'Konso Test' : 'Konso';
// A test build gets its name in the page title and on the home screen, so it is never mistaken for the real one.
if (test) {
  const p = path.join(out, 'index.html');
  const html = fs.readFileSync(p, 'utf8');
  const html2 = html
    .replace('<title>Konso</title>', '<title>Konso Test</title>')
    .replace('name="apple-mobile-web-app-title" content="Konso"', 'name="apple-mobile-web-app-title" content="Konso Test"');
  if (html2 === html) throw new Error('index.html: title not found');
  fs.writeFileSync(p, html2);
}

const manifest = {
  id: './',
  name,
  short_name: name,
  description: 'Fuel consumption and car maintenance tracker. Offline, private, open source.',
  start_url: './',
  scope: './',
  display: 'standalone',
  orientation: 'any',
  background_color: '#f9f9ff',
  theme_color: '#f9f9ff',
  categories: ['utilities', 'productivity', 'finance'],
  icons: [
    { src: 'icons/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
    { src: 'icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: 'icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: 'icons/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
};
fs.writeFileSync(path.join(out, 'manifest.webmanifest'), JSON.stringify(manifest, null, 2) + '\n');
files.push('manifest.webmanifest');
files.sort();

// Version = hash of every file: any change publishes a new offline cache.
const h = crypto.createHash('sha256');
for (const f of files) h.update(f + '\0').update(fs.readFileSync(path.join(out, f)));
const version = h.digest('hex').slice(0, 12);
const sw = fs
  .readFileSync(path.join(WEB, 'sw.js'), 'utf8')
  .replace("'__VERSION__'", JSON.stringify(version))
  .replace('__FILES__', JSON.stringify(files));
fs.writeFileSync(path.join(out, 'sw.js'), sw);
// No Jekyll processing on GitHub Pages: files are served exactly as they are.
fs.writeFileSync(path.join(out, '.nojekyll'), '');

console.log(`${name}: ${files.length} files, version ${version}, in ${out}`);
